with filtered as (select id, full_name, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, cast(is_remote as int) is_remote_flag, round(salary * 1.07, 2) salary_scaled, coalesce(job_title, 'NONE') job_title_filled from employees where job_title is not null and hire_date >= date '2023-08-22') select id, full_name, job_title, is_remote_flag, job_title_filled from (select *, row_number() over (partition by level order by hire_date desc, id) as row_num from filtered) ranked where row_num = 1
